#: The first list (owner's design, 22 Nov: rent, utilities, marketing, supplies, salary); whoever keeps the expenses
#: renames, adds or retires them on the Expenses tab. Written out here so later code cannot change what this did.
FIRST_CATEGORIES = ("Rent", "Utilities", "Salary", "Marketing", "Supplies", "Other")


def add_categories(apps, schema_editor):
    Category = apps.get_model("billing", "ExpenseCategory")
    for name in FIRST_CATEGORIES:
        Category.objects.get_or_create(name=name)


def remove_categories(apps, schema_editor):
    apps.get_model("billing", "ExpenseCategory").objects.filter(name__in=FIRST_CATEGORIES, expenses__isnull=True).delete()


